import assert from'node:assert/strict';import test from'node:test';import{PlatformError}from'../../src/foundation/index.js';import{BUNDLE_PACKAGE_CONTROLS,BUNDLE_PACKAGE_INVARIANTS,BUNDLES_PACKAGES_ELIGIBILITY_ERROR_CODE,BundlesPackagesEligibilityDescriptor as D,BundlesPackagesEligibilityProfile as P}from'../../src/product-catalog-resource-management/index.js';const K=['responsibilities','controls','recordFields','componentTypes','eligibilityReferences','lifecycleStates','validationRules','recovery','invariants'];const complete=d=>{const x={};for(const k of K)x[k]=d[k]();return new P({profileName:'Bundles Packages',...x})};test('ARCH-024-07 exposes composition controls eligibility and invariants',()=>{const d=new D();assert.ok(d.responsibilities().includes('component-cardinality'));assert.ok(d.controls().includes(BUNDLE_PACKAGE_CONTROLS.ACYCLIC));assert.ok(d.eligibilityReferences().includes('entitlement-eligibility'));assert.ok(d.invariants().includes(BUNDLE_PACKAGE_INVARIANTS.GOVERNED_AI))});test('ARCH-024-07 validates safeguards and rejects bundle shortcuts',()=>{const d=new D();assert.equal(d.validateProfile(complete(d)).isValid,true);const x=d.validateProfile({cyclicComposition:true,unpinnedComponents:true,priceAuthorizesEligibility:true,fabricatedEligibility:true});assert.equal(x.isValid,false);assert.match(x.errors.join('\n'),/cyclic composition/);assert.match(x.errors.join('\n'),/unpinned components/);assert.match(x.errors.join('\n'),/price authorizing eligibility/)});test('ARCH-024-07 detects incomplete metadata and preserves immutability',()=>{class I extends D{controls(){return []}}assert.throws(()=>new I().assertArchitecture(),e=>e instanceof PlatformError&&e.code===BUNDLES_PACKAGES_ELIGIBILITY_ERROR_CODE);const p=complete(new D());assert.ok(Object.isFrozen(p));assert.throws(()=>p.lifecycleStates.push('x'),TypeError)});
